# ─────────────────────────────────────────────

fft_array = np.array(fft_data, dtype=complex)
raw = np.array(fft_data)

# Helper: search for flag in a string
def find_flag(label, s):
    sl = s.lower()
    if 'udctf' in sl or 'flag' in sl or '{' in s:
        print(f"\n[!!!] FLAG FOUND in {label}:")
        # print surrounding context
        idx = sl.find('udctf') if 'udctf' in sl else sl.find('{')
        print(s[max(0,idx-5):idx+50])
    else:
        print(f"[ ] {label}: {s[:80]}")

# --- Method 1: IFFT rounded ---
sig = np.round(np.fft.ifft(fft_array).real).astype(int)
find_flag("IFFT->ASCII", ''.join(chr(v % 256) for v in sig))

# --- Method 2: irfft rounded ---
sig_r = np.round(np.fft.irfft(fft_array)).astype(int)
find_flag("irfft->ASCII", ''.join(chr(v % 256) for v in sig_r))

# --- Method 3: raw as bytes ---
find_flag("Raw mod256", ''.join(chr(int(v) % 256) for v in raw))

# --- Method 4: raw as uint8 bytes -> decode utf8 ---
try:
    b = bytes([int(v) % 256 for v in raw])
    find_flag("Raw bytes utf8", b.decode('utf-8', errors='replace'))
except: pass

# --- Method 5: XOR each value with common keys ---
for key in [0x20, 0x42, 0x55, 0x61, 0xFF, 13, 42]:
    s = ''.join(chr((int(v) ^ key) % 256) for v in raw)
    find_flag(f"Raw XOR 0x{key:02X}", s)

# --- Method 6: differences between consecutive values ---
diffs = np.diff(raw).astype(int)
find_flag("Diffs mod256", ''.join(chr(int(v) % 256) for v in diffs))

# --- Method 7: IFFT magnitude as ASCII ---
mag = np.round(np.abs(np.fft.ifft(fft_array))).astype(int)
find_flag("IFFT magnitude", ''.join(chr(v % 256) for v in mag))

# --- Method 8: try base64 on raw bytes ---
try:
    b = bytes([abs(int(v)) % 256 for v in raw])
    decoded = base64.b64decode(b + b'==').decode('utf-8', errors='replace')
    find_flag("Base64 decode", decoded)
except: pass

# --- Method 9: look at only non-zero IFFT imaginary parts ---
imag = np.round(np.fft.ifft(fft_array).imag).astype(int)
find_flag("IFFT imag->ASCII", ''.join(chr(v % 256) for v in imag))

# --- Method 10: subtract mean, scale to ASCII range ---
sig_norm = sig - sig.min()
if sig_norm.max() > 0:
    sig_scaled = (sig_norm * 94 / sig_norm.max() + 32).astype(int)
    find_flag("IFFT scaled to ASCII", ''.join(chr(v) for v in sig_scaled))

print("\n--- Raw data stats ---")
print(f"N={len(fft_data)}, min={int(min(fft_data))}, max={int(max(fft_data))}")
print(f"First 10 values: {fft_data[:10]}")